// Run with the omp browser helper after opening an isolated Chromium tab.
export const captureAll = async(mock)=>await mock.run(async({page,tab,assert})=>{const dir='/Users/joshuapare/omniview/screenshots/extension-registry/';const saved=[];async function shot(name){await page.screenshot({path:dir+name});saved.push(name)}async function check(expr,msg){assert(await tab.evaluate(expr),msg)}await page.goto('http://127.0.0.1:5278/');await page.setViewport({width:1440,height:900,deviceScaleFactor:1});await check('__mock.state.view==="points"','point view');await shot('01-registry-overview.png');await page.click('[data-sub="metadata"]');await check('__mock.state.sub==="metadata"','metadata');await shot('02-point-metadata.png');await page.click('[data-view="plugins"]');await check('__mock.state.view==="plugins"','plugin view');await shot('03-plugin-coverage.png');await page.click('[data-pending]');await check('__mock.state.issue==="pending"&&__mock.state.view==="issues"','pending');await shot('04-pending-target.png');await page.click('[data-issue="crash"]');await check('__mock.state.issue==="crash"','crash');await shot('05-quarantine-error.png');await page.click('#reenable');await page.waitForSelector('[role="dialog"]');await shot('06-reenable-confirmation.png');await page.keyboard.press('Escape');await check('!document.querySelector("[role=dialog]")','dismissed');await page.click('[data-view="context"]');await page.click('#evaluate');await check('__mock.state.evaluated&&__mock.state.context==="Pod"','Pod');await shot('07-context-quarantine.png');await page.select('#resource','Deployment');await page.click('#evaluate');await check('__mock.state.context==="Deployment"','Deployment');await shot('08-context-selected.png');await page.click('[data-view="points"]');await page.type('#search','no-such-point');await check('document.querySelector(".list").textContent.includes("No extension points match")','empty');await shot('09-empty-filter.png');await page.click('#pause');await check('__mock.state.paused','paused');await page.click('#pause');await check('!__mock.state.paused','resumed');await page.goto('http://127.0.0.1:5278/?theme=light');await shot('10-light-theme.png');return saved;},{timeout:120});
